.panel {
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
  max-width: 560px;
}

.actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
  margin: 0;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

/* El HTML aprobado usa blanco puro para el input; el sistema no tiene token de
   blanco, así que se usa el neutro claro más cercano (--bw-warm-cream). */
.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  font-family: inherit;
  background: var(--bw-warm-cream);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.primaryBtn:hover:not(:disabled) {
  opacity: 0.88;
}

.primaryBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.threadCount {
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.loading {
  font-size: var(--bw-size-input);
  color: var(--bw-text-secondary);
  padding: 24px 18px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.error {
  font-size: var(--bw-size-input);
  color: var(--bw-error-text);
  padding: 12px 14px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 8px;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  font-size: var(--bw-size-label);
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: all 0.12s;
}

.pageBtn:not(.pageBtnActive):hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

.pageBtnActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageCtrl {
  color: var(--bw-input-placeholder);
}

/* Para el motivo del botón "Nuevo contacto": visible solo para lectores de
   pantalla, pero conectado al botón con aria-describedby (F-128). */
.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

