import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es LA PANTALLA, no un componente de presentación: llama a `fetchThreadPage`
 * con `profile.orgId` y posee el estado de búsqueda y de página. `now` es
 * inyectable para que los tests no dependan del reloj.
 */

interface Props {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /**
   * F-118: la pasa el shell desde `App.tsx`. MSG-02 no existía cuando se escribió
   * esta pantalla y abrir un hilo no lleva a ningún sitio: se declara porque es
   * la firma pública del componente, y se ignora — no cambia nada de lo que se
   * pide.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Convierte el fallo de `fetchThreadPage` en texto para el aviso.
 *
 * PostgREST rechaza con un objeto plano `{ code, message }`: `String(e)` daría
 * `[object Object]` y `e.message` daría `undefined` (F-020, F-128). Se sacan
 * `code` y/o `message` cuando existan y se pintan junto a la frase para humanos.
 */
function describeError(e: unknown): string {
  if (typeof e === 'object' && e !== null) {
    const maybe = e as { code?: unknown; message?: unknown };
    const parts: string[] = [];
    if (typeof maybe.code === 'string' && maybe.code.length > 0) parts.push(maybe.code);
    if (typeof maybe.message === 'string' && maybe.message.length > 0) parts.push(maybe.message);
    if (parts.length > 0) return parts.join(' — ');
  }
  if (e instanceof Error) return e.message;
  return String(e);
}

export function Messages({ profile, now }: Props) {
  const [search, setSearch] = useState('');
  const [appliedSearch, setAppliedSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let disposed = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: appliedSearch, page })
      .then((res) => {
        if (disposed) return;
        setThreads(res.threads);
        setTotal(res.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (disposed) return;
        setError(e);
        setLoading(false);
      });

    return () => {
      disposed = true;
    };
  }, [profile.orgId, appliedSearch, page]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setAppliedSearch(search.trim());
    setPage(1);
  };

  const pages = pageCount(total);
  const totalLabel = total.toLocaleString('es-ES');
  const countLabel = `${totalLabel} ${total === 1 ? 'hilo' : 'hilos'} · Página ${page} de ${pages}`;

  return (
    <section className={styles.panel}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      <div className={styles.actions}>
        <form className={styles.searchWrap} role="search" onSubmit={handleSubmit}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </form>
        {/* DIR-01 no está entre las pantallas del MVP (Plan §9): el control
            existe pero no lleva a ninguna parte, se pinta deshabilitado con el
            motivo (F-023 e). El motivo va con aria-describedby para que sea
            accesible; es la misma forma que el botón de subida de INV-01. */}
        <button
          type="button"
          className={styles.primaryBtn}
          aria-describedby="nuevo-contacto-razon"
          disabled
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span id="nuevo-contacto-razon" className={styles.srOnly}>
          El Directorio queda fuera del MVP.
        </span>
        <span className={styles.threadCount} data-testid="pag-info">
          {countLabel}
        </span>
      </div>

      {loading ? (
        <p className={styles.loading}>Cargando hilos...</p>
      ) : error ? (
        /* F-127: el aviso de error lleva role="alert"; F-128: enseña el error de
           verdad, no una frase genérica que se coma el código. */
        <p role="alert" className={styles.error}>
          No se pudieron cargar los hilos. {describeError(error)}
        </p>
      ) : (
        <ThreadList
          threads={threads}
          onOpen={() => {}}
          {...(now !== undefined ? { now } : {})}
        />
      )}

      {!loading && !error && total > 0 && (
        <nav className={styles.pagination} aria-label="Paginación">
          <button
            type="button"
            className={`${styles.pageBtn} ${styles.pageCtrl}`}
            aria-label="Página anterior"
            disabled={page <= 1}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            ‹
          </button>
          {Array.from({ length: pages }, (_, i) => i + 1).map((n) => (
            <button
              key={n}
              type="button"
              className={`${styles.pageBtn} ${n === page ? styles.pageBtnActive : ''}`}
              aria-label={`Página ${n}`}
              aria-current={n === page ? 'page' : undefined}
              onClick={() => setPage(n)}
            >
              {n}
            </button>
          ))}
          <button
            type="button"
            className={`${styles.pageBtn} ${styles.pageCtrl}`}
            aria-label="Página siguiente"
            disabled={page >= pages}
            onClick={() => setPage((p) => Math.min(pages, p + 1))}
          >
            ›
          </button>
        </nav>
      )}
    </section>
  );
}

