/* El HTML aprobado usa blanco puro (#fff) para la tarjeta de lista; el sistema
   de diseño no tiene token de blanco, así que se usa el neutro claro más
   cercano del sistema (--bw-warm-cream). */
.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row:not(:last-child) {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.rowBtn {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  color: inherit;
  text-align: left;
  transition: background 0.1s;
}

.rowBtn:hover {
  background: var(--bw-hover-surface);
}

.rowTop {
  grid-column: 1;
  grid-row: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.country {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.time {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  align-self: center;
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-text-secondary);
  white-space: nowrap;
}

.rowBottom {
  grid-column: 1;
  grid-row: 2;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: 12px;
  color: var(--bw-text-secondary);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Tonos del badge de estado: la spec da hex pero un componente no escribe
   hex (§6.1); el mapeo hex→token vive aquí. */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-hint-steel);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* Estado vacío: botón deshabilitado y motivo visible (F-128). */
.empty {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  padding: 48px 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.emptyText {
  font-size: 14px;
  color: var(--bw-text-secondary);
  line-height: 1.6;
  max-width: 420px;
}

.emptyBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  cursor: not-allowed;
  opacity: 0.5;
}

.emptyHint {
  font-size: 12px;
  color: var(--bw-text-secondary);
}

