import { previewLabel, relativeTime, stateTone, type ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01 (presentacional).
 *
 * Pinta las filas que recibe en el orden en que las recibe — el orden lo fija el
 * servidor (`last_item_at` desc). No carga datos ni pagina.
 *
 * Estado vacío (F-128): con `threads` vacío no se pinta una lista colgada, sino
 * un estado vacío con el botón `Ir al Directorio` deshabilitado y el motivo
 * visible — el Directorio queda fuera del MVP, misma forma que el botón de
 * subida de INV-01 (F-023 e).
 */

interface Props {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /** Avisa con el ID del hilo, no con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: Props) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((t) => {
        const tone = stateTone(t.state);
        return (
          <li key={t.id} className={styles.row}>
            {/* El botón va DENTRO del `<li>` para que el li conserve su rol
                `listitem` (F-131): un `role="button"` sobre el li lo sustituiría
                y rompería el contrato de unidad. Es este botón el que lleva el
                nombre accesible del hilo. */}
            <button
              type="button"
              className={styles.rowBtn}
              aria-label={t.counterpartyName}
              onClick={() => onOpen(t.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.org}>{t.counterpartyName}</span>
                <span className={styles.country}>{t.counterpartyCountry}</span>
              </span>
              <span className={styles.time}>{relativeTime(t.lastItemAt, now)}</span>
              <span className={styles.rowBottom}>
                <span className={styles.preview}>{previewLabel(t.lastItem)}</span>
                <span className={`${styles.stateBadge} ${styles[tone]}`}>{t.state}</span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
